68	export function attachWebSocket(server: Server) {
69	  const wss = new WebSocketServer({ noServer: true });
70	
71	  // Only signed-in members of the workspace may connect.
72	  server.on('upgrade', async (req: IncomingMessage, socket: Duplex, head: Buffer) => {
73	    try {
74	      const url = new URL(req.url ?? '/', 'http://localhost');
75	      if (url.pathname !== '/ws') return refuse(socket, 404, 'Not Found');
76	      const workspace = url.searchParams.get('workspace') ?? '';
77	      const afterParam = url.searchParams.get('after');
78	      const after = afterParam !== null && /^\d+$/.test(afterParam) ? Number(afterParam) : null;
79	
80	      const session = await getSession(req);
81	      if (!session) return refuse(socket, 401, 'Unauthorized');
82	      if (!roleIn(session, workspace)) return refuse(socket, 403, 'Forbidden');
83	
84	      wss.handleUpgrade(req, socket, head, (ws) => {
85	        const client: Client = { socket: ws, workspace, lastSent: Number.MAX_SAFE_INTEGER, chain: Promise.resolve() };
86	        // register first, so frames published while we replay are queued, not lost
87	        clients.add(client);
88	        queue(client, () => startClient(client, after));
89	        ws.on('close', () => clients.delete(client));
90	        ws.on('error', () => clients.delete(client));
91	      });
92	    } catch (err) {
93	      console.error('ws upgrade failed:', (err as Error).message);
94	      refuse(socket, 500, 'Internal Server Error');
95	    }
96	  });
