1	import { collections, isDup } from './store.js';
2	import { emitSafely } from './events.js';
3	
4	// Agent takes a conversation. One atomic database operation, so six agents at the same
5	// instant get exactly one winner:
6	//   - matches only if nobody holds it, or this agent already does
7	//   - if it does not match, upsert tries to create it; the unique index on
8	//     (workspace, contact) then fails for anyone who lost, which means "held by someone else"
9	// Returns true if this agent holds it now.
10	export async function claimConversation(workspace: string, contact: string, agent: string): Promise<boolean> {
11	  const { conversations } = await collections();
12	  try {
13	    const before = await conversations.findOneAndUpdate(
14	      { workspace, contact, assignee: { $in: [null, agent] } },
15	      { $set: { assignee: agent }, $setOnInsert: { state: 'open', lastActivityAt: new Date(), createdAt: new Date() } },
16	      { upsert: true, returnDocument: 'before' },
17	    );
18	    if (!before || before.assignee !== agent) {
19	      await emitSafely(workspace, { type: 'conversation.assigned', contact, assignee: agent });
20	    }
21	    return true;
22	  } catch (err) {
23	    if (isDup(err)) return false;
24	    throw err;
25	  }
26	}
27	
28	// Admin takes a conversation from whoever holds it (roles are enforced here, not by the IdP).
29	export async function takeOverConversation(workspace: string, contact: string, agent: string) {
30	  const { conversations } = await collections();
31	  const res = await conversations.updateOne({ workspace, contact }, { $set: { assignee: agent } });
32	  if (res.modifiedCount) await emitSafely(workspace, { type: 'conversation.assigned', contact, assignee: agent });
33	  return res.matchedCount > 0;
34	}
35	
36	// Holder gives the conversation back (admins may release anyone's).
37	export async function releaseConversation(workspace: string, contact: string, agent: string, isAdmin: boolean) {
38	  const { conversations } = await collections();
39	  const filter = isAdmin ? { workspace, contact } : { workspace, contact, assignee: agent };
40	  const res = await conversations.updateOne({ ...filter, assignee: { $ne: null } }, { $set: { assignee: null } });
41	  if (res.modifiedCount) await emitSafely(workspace, { type: 'conversation.assigned', contact, assignee: null });
42	  return res.modifiedCount > 0;
43	}
