45	// Close or reopen. A new customer message does not reopen automatically (see DECISIONS.md).
46	export async function setConversationState(workspace: string, contact: string, state: 'open' | 'closed') {
47	  const { conversations } = await collections();
48	  const res = await conversations.updateOne({ workspace, contact, state: { $ne: state } }, { $set: { state } });
49	  if (res.modifiedCount) await emitSafely(workspace, { type: 'conversation.state', contact, state });
