        <circle cx="20" cy="20" r="19.5" fill="none" stroke="white" strokeOpacity="0.25" />
        <text x="20" y="20" dy="0.35em" textAnchor="middle" fontSize="14" fontWeight="600" fill="white" fontFamily="Inter, system-ui, sans-serif">
          {text}
        </text>
      </svg>
    </span>
  );
}

export { Avatar };
